-- Generated by `supabase migration new`; timestamp ordered after existing workflow schema.
-- Invoker rights preserve the existing owner policies and never use a service-role key.
alter table public.company_workflows add constraint company_workflows_id_company_unique unique(id,company_id);
create table public.company_workflow_runs (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  workflow_id uuid not null,
  created_by uuid not null references auth.users(id),
  name text not null,
  nodes jsonb not null check(jsonb_typeof(nodes)='array' and jsonb_array_length(nodes) between 1 and 50),
  edges jsonb not null check(jsonb_typeof(edges)='array' and jsonb_array_length(edges)<=100),
  status text not null default 'ready' check(status in ('ready','running','review','completed','failed','cancelled')),
  cursor integer not null default 0 check(cursor between 0 and 50),
  version integer not null default 0 check(version>=0),
  steps jsonb not null default '[]'::jsonb check(jsonb_typeof(steps)='array' and jsonb_array_length(steps)<=51),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key(workflow_id,company_id) references public.company_workflows(id,company_id) on delete restrict
);
create index company_workflow_runs_company_created_idx on public.company_workflow_runs(company_id,created_at desc);
create index company_workflow_runs_workflow_idx on public.company_workflow_runs(workflow_id,company_id);
alter table public.company_workflow_runs add constraint company_workflow_runs_id_company_unique unique(id,company_id);
alter table public.company_tasks add column workflow_run_id uuid, add column workflow_node_id uuid,
  add constraint company_tasks_workflow_run_company_fk foreign key(workflow_run_id,company_id) references public.company_workflow_runs(id,company_id),
  add constraint company_tasks_workflow_pair_check check((workflow_run_id is null)=(workflow_node_id is null));
create unique index company_tasks_workflow_attempt_unique on public.company_tasks(workflow_run_id,workflow_node_id) where workflow_run_id is not null;
alter table public.company_workflow_runs enable row level security;
revoke all on public.company_workflow_runs from anon, authenticated;
grant select,insert,update on public.company_workflow_runs to authenticated;
create policy "owners read workflow runs" on public.company_workflow_runs for select to authenticated using(private.is_company_owner(company_id));
create policy "owners create workflow runs" on public.company_workflow_runs for insert to authenticated with check(created_by=(select auth.uid()) and private.is_company_owner(company_id));
create policy "owners update workflow runs" on public.company_workflow_runs for update to authenticated using(private.is_company_owner(company_id)) with check(created_by=(select auth.uid()) and private.is_company_owner(company_id));

create function public.guard_workflow_run() returns trigger language plpgsql security invoker set search_path='' as $$
declare w public.company_workflows;
begin
  if TG_OP='INSERT' then
    select * into w from public.company_workflows where id=new.workflow_id and company_id=new.company_id;
    if not found or w.status='archived' or new.nodes is distinct from w.nodes or new.edges is distinct from w.edges or new.name is distinct from w.name
      or new.status<>'ready' or new.cursor<>0 or new.version<>0 or new.steps<>'[]'::jsonb then
      raise exception 'run must start with the saved workflow snapshot' using errcode='23514';
    end if;
  else
    if (new.id,new.company_id,new.workflow_id,new.created_by,new.name,new.nodes,new.edges,new.created_at)
      is distinct from (old.id,old.company_id,old.workflow_id,old.created_by,old.name,old.nodes,old.edges,old.created_at) then
      raise exception 'run identity and snapshot are immutable' using errcode='23514';
    end if;
    if new.version<>old.version+1 or old.status in ('completed','failed','cancelled') then
      raise exception 'invalid run version or terminal state' using errcode='23514';
    end if;
    if not ((old.status in ('ready','review') and new.status in ('running','cancelled')) or
            (old.status='running' and new.status in ('ready','review','completed','failed'))) then
      raise exception 'invalid run transition' using errcode='23514';
    end if;
  end if;
  new.updated_at=now();
  return new;
end;
$$;
revoke all on function public.guard_workflow_run() from public,anon,authenticated;
create trigger workflow_run_guard before insert or update on public.company_workflow_runs for each row execute function public.guard_workflow_run();

-- All aggregations happen in PostgreSQL; REST row limits never truncate statistics.
create function public.company_dashboard(p_company_id uuid) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare groups jsonb; totals jsonb;
begin
  if not coalesce(private.is_company_owner(p_company_id),false) then
    raise exception 'company owner required' using errcode='42501';
  end if;
  with records as (
    select 'agents' k,status s from public.company_ai_agents where company_id=p_company_id
    union all select 'tasks',status from public.company_tasks where company_id=p_company_id
    union all select 'leads',stage from public.company_leads where company_id=p_company_id
    union all select 'quotes',status from public.company_quotes where company_id=p_company_id
    union all select 'jobs',status from public.company_jobs where company_id=p_company_id
    union all select 'workflows',status from public.company_workflows where company_id=p_company_id
    union all select 'runs',status from public.company_workflow_runs where company_id=p_company_id
    union all select 'sponsorOffers',status from public.sponsorship_offers where sponsor_company_id=p_company_id
    union all select 'sponsorApplications',status from public.sponsorship_requests where applicant_company_id=p_company_id
    union all select 'sponsorInbox',status from public.sponsorship_requests where sponsor_company_id=p_company_id
  ), grouped as (select k,s,count(*) n from records group by k,s),
  categories as (select k,jsonb_object_agg(s,n) statuses,sum(n) total from grouped group by k)
  select coalesce(jsonb_object_agg(k,statuses),'{}'::jsonb),coalesce(jsonb_object_agg(k,total),'{}'::jsonb) into groups,totals from categories;
  return jsonb_build_object(
    'counts',jsonb_build_object('agents',0,'tasks',0,'leads',0,'quotes',0,'jobs',0,'workflows',0,'runs',0,'sponsorOffers',0,'sponsorApplications',0,'sponsorInbox',0)||totals,
    'statuses',groups,
    'ownedCompanies',(select count(*) from public.companies where owner_id=(select auth.uid())),
    'quotedAmounts',coalesce((select jsonb_agg(v order by currency,status) from (
      select currency,status,count(*) count,sum(amount)::text amount from public.company_quotes where company_id=p_company_id group by currency,status
    ) v),'[]'::jsonb)
  );
end;
$$;
revoke all on function public.company_dashboard(uuid) from public,anon;
grant execute on function public.company_dashboard(uuid) to authenticated;
